def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0)

    # Network rule: self_employed with requested_limit > 7000 -> manual review,
    # unless the partner declined it (a decline stays a decline).
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 7000
            and decision != "decline"):
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "decline":
        return {"action": "decline", "limit": 0}
    # refer or anything undecided -> manual review
    return {"action": "queue_review", "limit": 0}
